# patch-listing-page.ps1
# Writes the full listing detail page with OfferButton wired in.

$ErrorActionPreference = 'Stop'
cd C:\Users\kevch\Desktop\ProjectFortuna\vendorhub

$path = 'src\app\listings\[region]\[suburb]\[slug]\page.tsx'
$b64 = ''

$content = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($b64))
$dir = [System.IO.Path]::GetDirectoryName($path)
if ($dir -and -not (Test-Path -LiteralPath $dir)) {
  New-Item -ItemType Directory -Force -Path $dir | Out-Null
}
Set-Content -LiteralPath $path -Value $content -Encoding UTF8 -NoNewline
$size = (Get-Item -LiteralPath $path).Length
Write-Host "Wrote $path ($size bytes)" -ForegroundColor Green

# Verify the Link and OfferButton imports made it in
$hasLink = Select-String -LiteralPath $path -Pattern '<Link href' -Quiet
$hasOffer = Select-String -LiteralPath $path -Pattern 'OfferButton' -Quiet
if ($hasLink) { Write-Host "  Link tag verified" -ForegroundColor Cyan }
else { Write-Host "  WARNING: Link tag NOT found" -ForegroundColor Red }
if ($hasOffer) { Write-Host "  OfferButton verified" -ForegroundColor Cyan }
else { Write-Host "  WARNING: OfferButton NOT found" -ForegroundColor Red }
